from modele import chapitre,E,Q

chapitre(13,'translations','Translations et parallélogrammes','4 · Géométrie et espace',
'Glissement · Conservations · Parallélogrammes · Frises et pavages',
['Construire l’image d’une figure par une translation.','Utiliser les propriétés de conservation et le lien avec le parallélogramme.','Reconnaître symétries, demi-tours, translations et parallélogrammes particuliers.'],
['Symétrie axiale, demi-tour et parallélogrammes (Cinquième).'],[
r'''\essSection{1}{Faire glisser une figure}
\begin{definition}La translation qui transforme A en A’ fait glisser toute figure selon la direction de la droite $(AA')$, dans le sens de A vers A’, d’une longueur égale à $AA'$. Elle déplace tous les points de la même façon, sans faire tourner la figure.\end{definition}
@FIG:cours-translation@
\begin{propriete}Une translation conserve les longueurs, les angles, l’alignement, le parallélisme et les aires. L’image d’une droite est une droite parallèle. Si A a pour image A’ et B pour image B’, alors $[AB]$ et $[A'B']$ sont parallèles et de même longueur, et ABB’A’ est un parallélogramme, éventuellement aplati.\end{propriete}
\begin{savoirfaire}[Construire une image]Sur quadrillage, compter le déplacement de A vers A’ et le reproduire depuis chaque sommet. Sans quadrillage, construire chaque image B’ comme quatrième sommet du parallélogramme ABB’A’, à la règle et au compas, puis relier les images dans le même ordre.\end{savoirfaire}''',
r'''\essSection{2}{Reconnaître une transformation}
\begin{definition}[Trois transformations]Une symétrie axiale retourne la figure par rapport à une droite. Un demi-tour, ou symétrie centrale, la fait tourner d’un demi-tour autour d’un point. Une translation la fait glisser sans la tourner. Toutes trois conservent les longueurs, les angles et les aires.\end{definition}
\begin{savoirfaire}[Distinguer]Par une translation, un segment et son image sont parallèles, de même longueur et orientés dans le même sens. Par un demi-tour, ils sont parallèles mais de sens opposés. Une symétrie axiale inverse le sens de rotation dans lequel on parcourt les sommets d’un polygone.\end{savoirfaire}
\begin{propriete}[Rappels sur les parallélogrammes]Un quadrilatère non croisé dont les diagonales ont le même milieu est un parallélogramme. Un parallélogramme dont les diagonales ont la même longueur est un rectangle ; s’il a des diagonales perpendiculaires, c’est un losange ; les deux à la fois, c’est un carré.\end{propriete}
\begin{exemple}[Frises et pavages]Une frise répète un motif par une même translation ; un pavage le répète dans deux directions. Les décors de l’Alhambra de Grenade et les dessins de M. C. Escher utilisent ainsi des translations.\end{exemple}'''],[
E('Décrire le glissement',r"Dans le repère, la translation transforme P(0 ; 0) en Q(3 ; 1). Quelle est l’image du point A(1 ; 2) ?",r"Le déplacement ajoute 3 à l’abscisse et 1 à l’ordonnée. L’image est donc $\res{A'(4\,;3)}$. Le même déplacement s’applique à chaque point.","Reproduire le déplacement horizontal et vertical.","assert (1+3,2+1)==(4,3)",figure='trans-01'),
E('Construire un triangle image',r"Construire l’image du triangle de sommets A(1 ; 1), B(3 ; 1) et C(2 ; 3) par le glissement de 3 carreaux vers la droite et 2 vers le haut.",r"On obtient $\res{A'(4\,;3),\ B'(6\,;3),\ C'(5\,;5)}$. Placer les trois images, puis relier dans le même ordre. Les côtés correspondants restent parallèles et de même longueur.","Appliquer le même déplacement aux trois sommets.","assert [(a+3,b+2) for a,b in [(1,1),(3,1),(2,3)]]==[(4,3),(6,3),(5,5)]",figure='trans-02'),
E('Un déplacement vers la gauche',r"Une translation déplace de 4 carreaux vers la gauche et 1 vers le bas. Donner l’image du point B(2 ; 3).",r"Vers la gauche, on soustrait 4 à l’abscisse ; vers le bas, on soustrait 1 à l’ordonnée. Donc $\res{B'(-2\,;2)}$.","Relier le sens du déplacement au signe du calcul.","assert (2-4,3-1)==(-2,2)",figure='trans-03'),
E('Conserver des mesures',r"Le triangle ABC a $AB=5$ cm, $\widehat{BAC}=42^\circ$ et une aire de 9 cm$^2$. Donner ces mesures pour son image A’B’C’ par une translation.",r"Une translation conserve longueurs, angles et aires. Donc $\res{A'B'=5\ \mathrm{cm}}$, $\res{\widehat{B'A'C'}=42^\circ}$ et l’aire de A’B’C’ vaut $\res{9\ \mathrm{cm}^2}$.","Citer la conservation adaptée à chaque mesure.","assert 5==5 and 42==42 and 9==9",figure='trans-04'),
E('Reconnaître une transformation',r"Les drapeaux 1, 2 et 3 sont des images du drapeau F. Pour chacun, dire s’il est obtenu par une symétrie axiale, un demi-tour ou une translation.",r"Le drapeau 1 a seulement glissé, sans tourner : $\res{\text{translation}}$. Le drapeau 2 est retourné par rapport à une droite verticale : $\res{\text{symétrie axiale}}$. Le drapeau 3 a tourné d’un demi-tour : $\res{\text{demi-tour}}$ ; ses segments sont parallèles à ceux de F mais de sens opposés.","Observer l’orientation du mât et du fanion.","F=[(Rational(24,5),0),(Rational(24,5),2),(6,Rational(8,5))]; assert [(x-Rational(26,5),y-Rational(2,5)) for x,y in F][0]==(Rational(-2,5),Rational(-2,5)) and [(Rational(39,5)-x,y) for x,y in F][2]==(Rational(9,5),Rational(8,5)) and [(13-x,2-y) for x,y in F][1]==(Rational(41,5),0)",figure='trans-05'),
E('Un parallélogramme',r"A a pour image A’ et B pour image B’ par une même translation. Les quatre points sont distincts et non alignés. Justifier que ABB’A’ est un parallélogramme.",r"Les segments $[AB]$ et $[A'B']$ sont parallèles et de même longueur, car $[A'B']$ est l’image de $[AB]$ par la translation. Dans l’ordre A, B, B’, A’, ce sont deux côtés opposés. Un quadrilatère non croisé ayant deux côtés opposés parallèles et de même longueur est un $\res{\text{parallélogramme}}$.","Respecter l’ordre des sommets du quadrilatère.","A=(0,0);B=(3,0);A2=(2,2);B2=(5,2); assert (B[0]-A[0],B[1]-A[1])==(B2[0]-A2[0],B2[1]-A2[1])",figure='trans-06'),
E('Reconnaître par les diagonales',r"Dans chaque figure, les diagonales $[AC]$ et $[BD]$ du quadrilatère ABCD se coupent en O ; les codages sont des données. Donner la nature de chaque quadrilatère.",r"Figure 1 : les diagonales ont le même milieu, c’est un $\res{\text{parallélogramme}}$. Figure 2 : même milieu et diagonales perpendiculaires, c’est un $\res{\text{losange}}$. Figure 3 : même milieu et diagonales de même longueur, c’est un $\res{\text{rectangle}}$.","Commencer par le milieu commun, puis ajouter le second codage.","assert True",figure='trans-07'),
E('Une frise',r"Les débuts de cinq motifs identiques d’une frise sont espacés de 4 cm. Quel glissement mène du premier motif au suivant ? du premier au cinquième ?",r"Du premier au suivant : translation de 4 cm vers la droite. Du premier au cinquième, on compte quatre intervalles : $4\times4=\res{16}$ cm vers la droite. Cinq motifs ne font que quatre écarts.","Compter les intervalles entre les motifs.","assert (5-1)*4==16",figure='trans-08'),
E('Image d’une droite',r"Une translation transforme la droite $(d)$ en $(d')$ et la droite $(\Delta)$ en $(\Delta')$. Les droites $(d)$ et $(\Delta)$ forment un angle de $35^\circ$. Que peut-on dire de $(d)$ et $(d')$ ? Quel angle forment $(d')$ et $(\Delta')$ ?",r"L’image d’une droite par une translation est une droite parallèle : $\res{(d')\parallel(d)}$. La translation conserve les angles : $(d')$ et $(\Delta')$ forment aussi un angle de $\res{35^\circ}$.","Utiliser les conservations.","assert 35==35",figure='trans-09'),
E('Deux déplacements',r"On déplace un point de 5 carreaux vers la droite et 2 vers le haut, puis de 3 vers la gauche et 4 vers le haut. Quel glissement unique donne le même résultat ?",r"Horizontalement : $5-3=2$ carreaux vers la droite. Verticalement : $2+4=6$ vers le haut. Le glissement total est donc de $\res{2\text{ carreaux à droite et }6\text{ vers le haut}}$.","Additionner séparément les déplacements sur chaque axe.","assert (5-3,2+4)==(2,6)",figure='trans-10'),
E('Construire sans quadrillage',r"Construire l’image du triangle EFG par la translation qui transforme E en K. Décrire la construction et la justifier.",r"L’image de E est K. On construit F’ tel que EFF’K soit un parallélogramme : on trace la parallèle à $(EK)$ passant par F et l’on reporte au compas la longueur EK, dans le même sens. On procède de même pour G’. L’image cherchée est le triangle $\res{KF'G'}$, de mêmes dimensions que EFG.","Construire des parallélogrammes ayant le côté [EK].","E_=(0,0);F=(2,-1);G=(1.5,1.5);K=(4,1); F2=(F[0]+4,F[1]+1); G2=(G[0]+4,G[1]+1); assert (F2[0]-F[0],F2[1]-F[1])==(K[0]-E_[0],K[1]-E_[1]) and (G2[0]-G[0],G2[1]-G[1])==(4,1)",figure='trans-11'),
E('Translation et parallélogramme',r"ABCD est un parallélogramme. On considère la translation qui transforme A en B. Démontrer qu’elle transforme D en C.",r"Notons D’ l’image de D. Par la propriété du cours, ABD’D est un parallélogramme : D’ est le quatrième sommet du parallélogramme construit sur A, B et D, dans cet ordre. Or ce quatrième sommet est C, puisque ABCD est un parallélogramme. Donc $\res{D'=C}$.","Utiliser l’unicité du quatrième sommet.","A=(0,0);B=(5,0);D=(1.5,2.5);C=(6.5,2.5); assert (D[0]+5,D[1])==C",figure='trans-12'),
E('Un pavage par translations',r"Un motif carré de 2 cm de côté est répété sans trou ni chevauchement sur 6 colonnes et 4 lignes. Combien de motifs utilise-t-on ? Donner l’aire totale et le glissement qui mène d’un motif au motif situé deux colonnes plus à droite et une ligne plus haut.",r"Il y a $6\times4=\res{24}$ motifs, chacun d’aire 4 cm$^2$. L’aire totale vaut $\res{96\ \mathrm{cm}^2}$. Le glissement demandé est de $\res4$ cm vers la droite et $\res2$ cm vers le haut. Les translations conservent la taille du motif.","Compter les copies et convertir le déplacement en longueurs.","assert 6*4==24 and 24*2**2==96 and (2*2,1*2)==(4,2)",figure='trans-13'),
E('Deux parterres',r"Le parterre triangulaire ABC est rectangle en A, avec $AB=6$ m, $AC=8$ m et $BC=10$ m. On le reproduit par la translation qui transforme A en D ; B a pour image E et C pour image F. Quelle longueur de bordure faut-il pour entourer les deux parterres ? Quelle est leur aire totale ? Quelle est la nature de ABED ?",r"DEF est l’image de ABC : mêmes longueurs, même angle droit. Chaque périmètre vaut $6+8+10=24$ m : il faut $\res{48\ \mathrm m}$ de bordure. Chaque aire vaut $\frac{6\times8}2=24$ m$^2$ : en tout $\res{48\ \mathrm m^2}$, les parterres étant disjoints. Enfin ABED est un $\res{\text{parallélogramme}}$ : A a pour image D et B pour image E.","Utiliser la conservation des longueurs et des aires.","assert 2*(6+8+10)==48 and 2*Rational(6*8,2)==48",figure='trans-14'),
E('Un angle transporté',r"Dans le triangle ABC, $\widehat{ABC}=70^\circ$. La translation qui transforme B en C transforme A en E. Démontrer que ABCE est un parallélogramme, puis calculer $\widehat{BCE}$.",r"A a pour image E et B pour image C : ABCE est un parallélogramme. Ainsi $(CE)\parallel(BA)$. Sur le prolongement de $[BC]$ au-delà de C, l’angle formé avec $[CE)$ est le correspondant de $\widehat{ABC}$ : il mesure $70^\circ$. Comme il est adjacent à $\widehat{BCE}$ sur un angle plat, $\widehat{BCE}=180-70=\res{110^\circ}$.","Utiliser des angles correspondants puis un angle plat.","assert 180-70==110",figure='trans-15')
],reperes=['Construire l’image d’une figure','Conservations, droites et angles','Translations et parallélogrammes','Reconnaître transformations, frises et pavages'],deco='translation')

chapitre(14,'milieux','La droite des milieux','4 · Géométrie et espace',
'Milieux · Parallèles · Moitié · Démonstrations',
['Connaître les trois théorèmes relatifs à la droite des milieux.','Choisir le théorème adapté pour prouver un parallélisme, un milieu ou calculer une longueur.','Rédiger une démonstration en plusieurs étapes.'],
['Demi-tour et parallélogrammes (Cinquième, chapitre 13).'],[
r'''\essSection{1}{Trois théorèmes}
\begin{theoreme}[1 · Droite des milieux]Dans un triangle, la droite qui passe par les milieux de deux côtés est parallèle au troisième côté.\end{theoreme}
\begin{theoreme}[2 · Segment des milieux]Dans un triangle, le segment qui joint les milieux de deux côtés mesure la moitié du troisième côté.\end{theoreme}
\begin{theoreme}[3 · Parallèle passant par un milieu]Dans un triangle, la droite qui passe par le milieu d’un côté et qui est parallèle à un deuxième côté coupe le troisième côté en son milieu.\end{theoreme}
@FIG:cours-milieux@
\begin{exemple}Dans le triangle ABC, I est le milieu de $[AB]$ et J celui de $[AC]$, avec $BC=9$ cm. D’après les théorèmes 1 et 2, $(IJ)\parallel(BC)$ et $IJ=\frac92=4{,}5$ cm.\end{exemple}''',
r'''\essSection{2}{Démontrer et choisir}
\begin{demonstration}[Idée de la preuve des théorèmes 1 et 2]Le demi-tour de centre J transforme I en un point K. Les diagonales $[AC]$ et $[IK]$ de AICK ont le même milieu J : c’est un parallélogramme, donc $(CK)\parallel(IB)$ et $CK=AI=IB$. Alors IBCK, qui a deux côtés opposés parallèles et de même longueur, est un parallélogramme : $(IJ)\parallel(BC)$ et $IJ=\frac12IK=\frac12BC$. La preuve détaillée, avec le théorème 3, figure dans « Comprendre les preuves ».\end{demonstration}
\begin{savoirfaire}[Choisir le théorème]Pour prouver un parallélisme à partir de deux milieux : théorème 1. Pour calculer une longueur à partir de deux milieux : théorème 2. Pour prouver qu’un point est un milieu à partir d’un milieu et d’un parallélisme : théorème 3.\end{savoirfaire}
\begin{savoirfaire}[Rédiger]« Dans le triangle ABC, I est le milieu de $[AB]$ et J est le milieu de $[AC]$. D’après le théorème de la droite des milieux, $(IJ)$ est parallèle à $(BC)$. » On cite le triangle, les données, le théorème, puis la conclusion.\end{savoirfaire}
\begin{attention}Les milieux doivent être donnés par l’énoncé ou démontrés, jamais lus sur le dessin. Le segment des milieux mesure la moitié du troisième côté : celui qui ne contient aucun des deux milieux.\end{attention}'''],[
E('Une longueur',r"Dans le triangle ABC, I est le milieu de $[AB]$, J celui de $[AC]$ et $BC=7{,}4$ cm. Calculer IJ.",r"Dans le triangle ABC, I et J sont les milieux de $[AB]$ et $[AC]$. D’après le théorème du segment des milieux, $IJ=\frac{BC}2=\frac{7{,}4}2=\res{3{,}7\ \mathrm{cm}}$.","Identifier le troisième côté.","assert Rational('7.4')/2==Rational('3.7')",figure='mil-01'),
E('Un parallélisme',r"Dans le triangle EFG, M est le milieu de $[EF]$ et N celui de $[EG]$. Démontrer que $(MN)$ et $(FG)$ sont parallèles.",r"Dans le triangle EFG, M est le milieu de $[EF]$ et N est le milieu de $[EG]$. D’après le théorème de la droite des milieux, $\res{(MN)\parallel(FG)}$.","Citer le triangle, les deux milieux et le théorème.","E_=(0,0);F=(6,0);G=(2,4); M=(3,0); N=(1,2); assert (N[0]-M[0])*(G[1]-F[1])-(N[1]-M[1])*(G[0]-F[0])==0",figure='mil-02'),
E('Retrouver un côté',r"Dans le triangle ABC, I et J sont les milieux respectifs de $[AB]$ et $[AC]$, et $IJ=5{,}2$ cm. Calculer BC.",r"D’après le théorème du segment des milieux, $IJ=\frac{BC}2$. Donc $BC=2\times5{,}2=\res{10{,}4\ \mathrm{cm}}$.","Doubler la longueur du segment des milieux.","assert 2*Rational('5.2')==Rational('10.4')",figure='mil-03'),
E('Un milieu',r"Dans le triangle ABC, I est le milieu de $[AB]$. La parallèle à $(BC)$ passant par I coupe $[AC]$ en J. Sachant que $AC=9$ cm, calculer AJ.",r"Dans le triangle ABC, la droite $(IJ)$ passe par le milieu I de $[AB]$ et elle est parallèle à $(BC)$. D’après le théorème 3, J est le milieu de $[AC]$. Donc $AJ=\frac92=\res{4{,}5\ \mathrm{cm}}$.","Utiliser un milieu et un parallélisme pour obtenir un milieu.","assert Rational(9,2)==Rational('4.5')",figure='mil-04'),
E('Choisir le théorème',r"Dans chaque figure, les codages sont des données. Indiquer le théorème qui permet de conclure, puis conclure."+Q(r"Figure 1 : les droites $(MN)$ et $(FG)$ sont-elles parallèles ?",r"Figure 2 : où se trouve le point N sur $[EG]$ ?",r"Figure 3 : sachant que $FG=8$ cm, que vaut MN ?"),r"a) M et N sont des milieux : théorème 1, $\res{(MN)\parallel(FG)}$. b) M est un milieu et $(MN)\parallel(FG)$ : théorème 3, $\res{N\text{ est le milieu de }[EG]}$. c) M et N sont des milieux : théorème 2, $MN=\frac82=\res{4\ \mathrm{cm}}$.","Repérer ce qui est donné : deux milieux, ou un milieu et un parallélisme.","assert Rational(8,2)==4",figure='mil-05'),
E('Le triangle des milieux',r"Le triangle ABC a pour côtés $AB=6$ cm, $AC=8$ cm et $BC=10$ cm. I, J et K sont les milieux de $[AB]$, $[AC]$ et $[BC]$. Calculer le périmètre du triangle IJK et le comparer à celui de ABC.",r"Chaque côté de IJK joint deux milieux : $IJ=\frac{10}2=5$, $JK=\frac62=3$ et $IK=\frac82=4$ cm. Le périmètre de IJK vaut $\res{12\ \mathrm{cm}}$, soit $\res{\text{la moitié}}$ de celui de ABC, qui vaut 24 cm.","Associer chaque segment des milieux au côté opposé.","assert Rational(10,2)+Rational(6,2)+Rational(8,2)==12 and 6+8+10==24",figure='mil-06'),
E('Un milieu, puis une longueur',r"Dans le triangle ABC, I est le milieu de $[AB]$ et la parallèle à $(BC)$ passant par I coupe $[AC]$ en J. On sait que $BC=9$ cm. Calculer IJ en justifiant chaque étape.",r"Étape 1 : $(IJ)$ passe par le milieu I de $[AB]$ et est parallèle à $(BC)$, donc J est le milieu de $[AC]$ (théorème 3). Étape 2 : I et J sont les milieux de $[AB]$ et $[AC]$, donc $IJ=\frac{BC}2=\res{4{,}5\ \mathrm{cm}}$ (théorème 2).","Démontrer d’abord que J est un milieu.","assert Rational(9,2)==Rational('4.5')",figure='mil-07'),
E('Une rédaction incomplète',r"Un élève écrit : « I est le milieu de $[AB]$ et J est un point de $[AC]$, donc $(IJ)$ est parallèle à $(BC)$. » Pourquoi ce raisonnement est-il incorrect ? Que faudrait-il savoir ?",r"Le théorème 1 demande deux milieux. Si J n’est pas le milieu de $[AC]$, $(IJ)$ n’est pas parallèle à $(BC)$ : la figure corrigée en donne un exemple. Il faudrait savoir que $\res{J\text{ est le milieu de }[AC]}$.","Vérifier toutes les hypothèses du théorème.","A=(0,0);B=(6,0);C=(2,4); I=(3,0); J=(1.5,3); assert (J[0]-I[0])*(C[1]-B[1])-(J[1]-I[1])*(C[0]-B[0])!=0",figure='mil-08'),
E('Dans un rectangle',r"ABCD est un rectangle de diagonale $AC=10$ cm. I est le milieu de $[AB]$ et J celui de $[BC]$. Démontrer que $(IJ)$ est parallèle à $(AC)$ et calculer IJ.",r"On se place dans le triangle ABC : I et J sont les milieux de $[AB]$ et $[BC]$. D’après les théorèmes 1 et 2, $\res{(IJ)\parallel(AC)}$ et $IJ=\frac{AC}2=\res{5\ \mathrm{cm}}$.","Choisir le triangle qui contient les deux milieux.","assert Rational(10,2)==5",figure='mil-09'),
E('Un parallélogramme de milieux',r"Dans le triangle ABC, I, J et K sont les milieux de $[AB]$, $[AC]$ et $[BC]$, avec $AB=7$ cm et $AC=5$ cm. Démontrer que AIKJ est un parallélogramme, puis calculer son périmètre.",r"I et K sont les milieux de $[AB]$ et $[BC]$ : $(IK)\parallel(AC)$, donc $(IK)\parallel(AJ)$. J et K sont les milieux de $[AC]$ et $[BC]$ : $(JK)\parallel(AB)$, donc $(JK)\parallel(AI)$. Les côtés opposés de AIKJ sont parallèles deux à deux : c’est un $\res{\text{parallélogramme}}$. Son périmètre vaut $2\times(3{,}5+2{,}5)=\res{12\ \mathrm{cm}}$.","Utiliser deux fois le théorème 1.","assert 2*(Rational(7,2)+Rational(5,2))==12",figure='mil-10'),
E('Des milieux de milieux',r"Dans le triangle ABC, $BC=12$ cm. I et J sont les milieux de $[AB]$ et $[AC]$, puis M et N sont les milieux de $[AI]$ et $[AJ]$. Calculer MN et justifier que $(MN)\parallel(BC)$.",r"Dans ABC : $IJ=\frac{12}2=6$ cm et $(IJ)\parallel(BC)$. Dans AIJ : M et N sont les milieux de $[AI]$ et $[AJ]$, donc $MN=\frac62=\res{3\ \mathrm{cm}}$ et $(MN)\parallel(IJ)$. Deux droites parallèles à une même troisième sont parallèles : $\res{(MN)\parallel(BC)}$.","Appliquer le théorème dans deux triangles emboîtés.","assert Rational(12,2)/2==3",figure='mil-11'),
E('Dans un trapèze',r"ABCD est un trapèze de bases $[AB]$ et $[CD]$, avec $AB=6$ cm et $CD=10$ cm. I est le milieu de $[AD]$. La parallèle à $(AB)$ passant par I coupe $[BD]$ en J et $[BC]$ en K. Démontrer que J et K sont des milieux, puis calculer IJ, JK et IK.",r"Dans ABD, la droite passe par le milieu I de $[AD]$, parallèlement à $(AB)$ : J est le milieu de $[BD]$ et $IJ=\frac62=\res{3\ \mathrm{cm}}$. Dans BDC, elle passe par le milieu J de $[BD]$, parallèlement à $(DC)$ car $(DC)\parallel(AB)$ : K est le milieu de $[BC]$ et $JK=\frac{10}2=\res{5\ \mathrm{cm}}$. Les points sont alignés : $IK=\res{8\ \mathrm{cm}}$.","Utiliser successivement les triangles ABD et BDC.","assert Rational(6,2)+Rational(10,2)==8==Rational(6+10,2)",figure='mil-12'),
E('Le théorème de Varignon',r"ABCD est un quadrilatère non croisé quelconque. I, J, K et L sont les milieux de $[AB]$, $[BC]$, $[CD]$ et $[DA]$. Démontrer que IJKL est un parallélogramme. Calculer son périmètre si $AC=8$ cm et $BD=6$ cm.",r"Dans ABC : $(IJ)\parallel(AC)$ et $IJ=\frac{AC}2$. Dans ACD : $(LK)\parallel(AC)$ et $LK=\frac{AC}2$. Donc $[IJ]$ et $[LK]$ sont parallèles et de même longueur : IJKL est un $\res{\text{parallélogramme}}$. De même $IL=JK=\frac{BD}2$. Périmètre : $8+6=\res{14\ \mathrm{cm}}$.","Utiliser une diagonale du quadrilatère dans deux triangles.","assert 2*Rational(8,2)+2*Rational(6,2)==14",figure='mil-13'),
E('Le point de concours des médianes',r"Dans le triangle ABC, I est le milieu de $[BC]$ et J celui de $[AC]$. Les médianes $(AI)$ et $(BJ)$ se coupent en G. K et L sont les milieux de $[AG]$ et $[BG]$. Démontrer que KLIJ est un parallélogramme. En déduire AG si $AI=9$ cm.",r"Dans ABG : $(KL)\parallel(AB)$ et $KL=\frac{AB}2$. Dans ABC : $(JI)\parallel(AB)$ et $JI=\frac{AB}2$. Ainsi KLIJ a deux côtés opposés parallèles et de même longueur : c’est un $\res{\text{parallélogramme}}$. Ses diagonales $[KI]$ et $[LJ]$ se coupent en G, leur milieu : $GK=GI$. Comme $AK=KG$, on a $AG=\frac23AI=\res{6\ \mathrm{cm}}$.","Combiner le théorème des milieux et les diagonales d’un parallélogramme.","assert Rational(2,3)*9==6",figure='mil-14'),
E('Le milieu de l’hypoténuse',r"ABC est rectangle en A, I est le milieu de $[BC]$ et J celui de $[AB]$. Démontrer que $(IJ)$ est la médiatrice de $[AB]$. En déduire que $IA=IB=IC$ et calculer IA si $BC=10$ cm.",r"Dans ABC, I et J sont des milieux : $(IJ)\parallel(AC)$. Or $(AC)\perp(AB)$, donc $(IJ)\perp(AB)$. La droite $(IJ)$ est perpendiculaire à $[AB]$ en son milieu J : c’est la $\res{\text{médiatrice de }[AB]}$, donc $IA=IB$. Comme $IB=IC=\frac{BC}2$, on obtient $IA=IB=IC=\res{5\ \mathrm{cm}}$. Ce résultat sera repris au chapitre 16.","Transporter l’angle droit par le parallélisme.","A=(0,0);B=(6,0);C=(0,8);I=(3,4); assert (I[0]-A[0])**2+(I[1]-A[1])**2==(I[0]-B[0])**2+(I[1]-B[1])**2==25",figure='mil-15')
],reperes=['Droite des milieux et parallélisme','Segment des milieux et longueurs','Parallèle passant par un milieu','Démonstrations en plusieurs étapes'],deco='milieux')

chapitre(15,'pythagore','Le théorème de Pythagore','4 · Géométrie et espace',
'Triangle rectangle · Longueurs · Réciproque · Contraposée',
['Calculer une longueur dans un triangle rectangle.','Démontrer qu’un triangle est rectangle ou qu’il ne l’est pas.','Distinguer théorème, réciproque et contraposée.'],
['Carrés, racines carrées et raisonnement (chapitres 4 et 12).'],[
r'''\essSection{1}{Calculer dans un triangle rectangle}
\begin{theoreme}[Théorème de Pythagore]Si un triangle ABC est rectangle en A, alors $BC^2=AB^2+AC^2$. Le côté opposé à l’angle droit, $[BC]$, est l’hypoténuse : c’est le plus long côté. Le théorème relie les aires des carrés construits sur les trois côtés.\end{theoreme}
@FIG:cours-pythagore@
\begin{exemple}Si $AB=3$ et $AC=4$ cm, alors $BC^2=9+16=25$, donc $BC=\sqrt{25}=5$ cm. Si $BC=13$ et $AB=5$ cm, alors $AC^2=13^2-5^2=144$, donc $AC=12$ cm.\end{exemple}
\begin{attention}On additionne les carrés pour chercher l’hypoténuse ; on soustrait pour chercher un côté de l’angle droit. Écrire d’abord l’égalité avec les noms des points aide à éviter cette confusion. Une longueur est positive : on prend la racine carrée.\end{attention}''',
r'''\essSection{2}{Réciproque et contraposée}
\begin{theoreme}[Réciproque du théorème de Pythagore]Si, dans un triangle ABC, $BC^2=AB^2+AC^2$, alors ce triangle est rectangle en A.\end{theoreme}
\begin{propriete}[Contraposée]Si, dans un triangle ABC, $BC^2\ne AB^2+AC^2$, alors ce triangle n’est pas rectangle en A. Lorsque $[BC]$ est le plus long côté, un angle droit ne pourrait être qu’en A, face à ce côté : le triangle n’est alors pas rectangle.\end{propriete}
\begin{savoirfaire}[Prouver ou réfuter]Identifier le plus long côté. Calculer séparément son carré et la somme des carrés des deux autres côtés. En cas d’égalité, la réciproque prouve que le triangle est rectangle ; sinon, la contraposée prouve qu’il ne l’est pas.\end{savoirfaire}
\begin{exemple}Côtés 6, 8 et 10 : $10^2=100=36+64$, le triangle est rectangle. Côtés 6, 8 et 11 : $11^2=121\ne100$, il ne l’est pas. Un dessin qui paraît rectangle ne suffit pas.\end{exemple}
\begin{savoirfaire}[Rédiger]Nommer le triangle et son angle droit, citer le théorème, écrire l’égalité, calculer, prendre la racine positive et conclure avec l’unité. Garder la valeur exacte avant l’arrondi final.\end{savoirfaire}'''],[
E('Chercher l’hypoténuse',r"ABC est rectangle en A, $AB=6$ cm et $AC=8$ cm. Calculer BC.",r"Dans ABC rectangle en A, le théorème de Pythagore donne $BC^2=6^2+8^2=100$. Comme BC est une longueur, $BC=\sqrt{100}=\res{10\ \mathrm{cm}}$. Elle dépasse bien chacun des deux autres côtés.","Additionner les carrés des côtés de l’angle droit.","assert sqrt(6**2+8**2)==10",figure='pyth-01'),
E('Chercher un côté de l’angle droit',r"ABC est rectangle en A, $AB=5$ cm et $BC=13$ cm. Calculer AC.",r"$[BC]$ est l’hypoténuse : $13^2=5^2+AC^2$. Donc $AC^2=169-25=144$ et $\res{AC=12\ \mathrm{cm}}$. Contrôle : $25+144=169$.","Soustraire au carré de l’hypoténuse.","assert sqrt(13**2-5**2)==12",figure='pyth-02'),
E('Une racine non entière',r"ABC est rectangle en A avec $AB=7$ cm et $AC=9$ cm. Donner BC exactement, puis au dixième.",r"$BC^2=49+81=130$, donc $\res{BC=\sqrt{130}\ \mathrm{cm}}$. Au dixième, $BC\approx\res{11{,}4\ \mathrm{cm}}$. On conserve la racine pour la valeur exacte.","Distinguer valeur exacte et approximation.","assert sqrt(7**2+9**2)==sqrt(130) and round(float(sqrt(130)),1)==11.4",figure='pyth-03'),
E('L’hypoténuse donnée',r"ABC est rectangle en A, $BC=17$ cm et $AB=15$ cm. Calculer AC.",r"$AC^2=BC^2-AB^2=289-225=64$. Donc $\res{AC=8\ \mathrm{cm}}$. $[BC]$ reste le plus long côté.","Repérer l’hypoténuse avant le calcul.","assert sqrt(17**2-15**2)==8",figure='pyth-04'),
E('Une réciproque',r"Un triangle ABC a pour côtés $AB=9$, $AC=12$ et $BC=15$ cm. Est-il rectangle ?",r"$[BC]$ est le plus long côté. $BC^2=225$ et $AB^2+AC^2=81+144=225$. L’égalité permet d’appliquer la réciproque du théorème de Pythagore : $\res{\text{ABC est rectangle en A}}$.","Comparer deux calculs menés séparément.","assert 15**2==9**2+12**2",figure='pyth-05'),
E('La contraposée',r"Un triangle ABC a pour côtés $AB=4$, $AC=5$ et $BC=7$ cm. Est-il rectangle ?",r"$[BC]$ est le plus long côté. $7^2=49$, tandis que $4^2+5^2=41$. Comme $49\ne41$, la $\res{\text{contraposée}}$ du théorème de Pythagore montre que ABC $\res{\text{n’est pas rectangle}}$ : s’il l’était, ces deux nombres seraient égaux.","Utiliser l’inégalité et la contraposée.","assert 7**2!=4**2+5**2 and 4+5>7",figure='pyth-06'),
E('Diagonale d’un rectangle',r"Un rectangle mesure 8 cm sur 6 cm. Calculer la longueur de sa diagonale.",r"La diagonale est l’hypoténuse d’un triangle rectangle dont les côtés de l’angle droit mesurent 8 et 6 cm. Son carré vaut $64+36=100$ : elle mesure $\res{10\ \mathrm{cm}}$.","Faire apparaître un triangle rectangle.","assert sqrt(8**2+6**2)==10",figure='pyth-07'),
E('Une échelle contre un mur',r"Une échelle de 2,5 m repose contre un mur perpendiculaire au sol. Son pied est à 0,8 m du mur. À quelle hauteur arrive-t-elle, au centimètre près ?",r"Le mur et le sol forment un triangle rectangle dont l’échelle est l’hypoténuse. $h^2=2{,}5^2-0{,}8^2=5{,}61$, donc $h=\sqrt{5{,}61}\approx\res{2{,}37\ \mathrm m}$. Les deux mesures étaient bien en mètres.","Modéliser la situation avant de calculer.","assert round(float(sqrt(Rational('2.5')**2-Rational('.8')**2)),2)==2.37",figure='pyth-08'),
E('Une distance dans un repère',r"Dans un repère orthonormé d’unité 1 cm, on donne $A(0\,;0)$, $B(6\,;0)$ et $C(0\,;8)$. Calculer BC.",r"$[AB]$ et $[AC]$ sont portés par les deux axes perpendiculaires, donc ABC est rectangle en A. $AB=6$ et $AC=8$ cm ; le théorème de Pythagore donne $\res{BC=10\ \mathrm{cm}}$. L’angle droit est justifié par le repère orthonormé.","Lire les écarts sur les axes puis utiliser Pythagore.","assert sqrt(6**2+8**2)==10",figure='pyth-09'),
E('Trouver le bon sommet',r"$AB=10{,}5$ cm, $AC=6{,}3$ cm et $BC=8{,}4$ cm. Démontrer que ABC est rectangle et préciser le sommet de l’angle droit.",r"Le plus long côté est $[AB]$. $AB^2=110{,}25$ et $AC^2+BC^2=39{,}69+70{,}56=110{,}25$. La réciproque montre que le triangle est rectangle au sommet opposé à $[AB]$, donc $\res{\text{en C}}$.","Placer l’angle droit en face du plus long côté.","assert Rational('10.5')**2==Rational('6.3')**2+Rational('8.4')**2",figure='pyth-10'),
E('Un losange',r"Un losange a des diagonales de 10 cm et 24 cm, qui se coupent perpendiculairement en leur milieu. Calculer son côté et son périmètre.",r"Un quart du losange est un triangle rectangle dont les côtés de l’angle droit mesurent 5 et 12 cm. Le côté du losange vaut $\sqrt{25+144}=\res{13}$ cm. Son périmètre est $4\times13=\res{52}$ cm.","Utiliser les demi-diagonales.","assert sqrt(5**2+12**2)==13 and 4*13==52",figure='pyth-11'),
E('Retrouver une aire',r"Un rectangle a une diagonale de 13 cm et une largeur de 5 cm. Calculer sa longueur puis son aire.",r"Pour la longueur $L$, $L^2=13^2-5^2=144$, donc $L=12$ cm. L’aire vaut $12\times5=\res{60\ \mathrm{cm}^2}$. Ne pas confondre la diagonale avec une dimension du rectangle.","Retrouver la dimension avant de calculer l’aire.","assert sqrt(13**2-5**2)==12 and 12*5==60",figure='pyth-12'),
E('Deux diagonales',r"Un câble suit la diagonale d’un rectangle de 8 m sur 6 m, puis celle d’un rectangle de 10 m sur 24 m. Calculer la longueur totale du câble.",r"La première diagonale vaut $\sqrt{8^2+6^2}=10$ m. La seconde vaut $\sqrt{10^2+24^2}=26$ m. On additionne les longueurs, pas leurs carrés : total $\res{36\ \mathrm m}$.","Traiter chaque triangle rectangle séparément.","assert sqrt(8**2+6**2)+sqrt(10**2+24**2)==36",figure='pyth-13'),
E('Une décision exacte',r"Une barre rigide de 8 cm doit relier les extrémités de deux côtés perpendiculaires de 4 cm et 7 cm. Est-elle assez longue ? Justifier sans arrondi.",r"La distance à couvrir vaut $\sqrt{4^2+7^2}=\sqrt{65}$ cm. Or $8^2=64<65$, donc $\sqrt{65}>8$ : la barre est $\res{\text{trop courte}}$. Un arrondi à 8 cm aurait masqué l’information décisive.","Comparer les carrés pour une décision exacte.","assert sqrt(65)>8",figure='pyth-14'),
E('Choisir un trajet',r"Un terrain rectangulaire mesure 12 m sur 5 m. Comparer un trajet le long de deux côtés consécutifs avec le trajet suivant la diagonale. Quelle longueur gagne-t-on avec la diagonale ?",r"Le trajet par les côtés vaut $12+5=17$ m. La diagonale vaut $\sqrt{12^2+5^2}=13$ m d’après le théorème de Pythagore. Le gain est $17-13=\res{4\ \mathrm m}$.","Calculer les deux parcours avant de comparer.","assert 12+5-sqrt(12**2+5**2)==4",figure='pyth-15')
],reperes=['Calculer une hypoténuse','Calculer un côté de l’angle droit','Réciproque et contraposée','Applications et précision des résultats'],deco='geometrie')
